import {
  ListTable,
  ListTableConstructorOptions,
  PivotChart,
  PivotChartConstructorOptions,
  register,
} from '@visactor/vtable'


registerAll()
register.chartModule('vchart', VChart)

const SimpleVSeedRender = (props: { vseed: VSeed }) => {
  const { vseed } = props
  const ref = useRef<HTMLDivElement>(null)
  const builderRef = useRef<Builder>(Builder.from({ chartType: 'line', dataset: [] }))
  const dark = useDark()
  const [locale, setLocale] = useState<Locale>('en-US')

  useEffect(() => {
    if (!ref.current) {
      return
    }
    const theme = dark ? 'dark' : 'light'
    const builder = Builder.from({ ...vseed, theme, locale })
    const spec = builder.build()

    builderRef.current = builder
    if (isPivotChart(vseed)) {
      const tableInstance = new PivotChart(ref.current, spec as PivotChartConstructorOptions)
      return () => tableInstance.release()
    } else if (isVChart(vseed)) {
      const vchart = new VChart(spec as ISpec, { dom: ref.current })
      vchart.renderSync()
      return () => vchart.release()
    } else if (isVTable(vseed)) {
      const tableInstance = new ListTable(ref.current, spec as ListTableConstructorOptions)
      return () => tableInstance.release()
    }
  }, [vseed, dark, locale])

  return (
    <div
      style={{ display: 'flex', flexDirection: 'column' }}
      onClick={() => {
        console.group(`selected ${vseed.chartType}`)
        console.log('builder', builderRef.current)
        console.log('spec', builderRef.current?.spec)
        console.log('vseed', builderRef.current?.vseed)
        console.log('advancedVSeed', builderRef.current?.advancedVSeed)
        console.groupEnd()
      }}
    >
      <div>
        {['en-US', 'zh-CN'].map((d) => {
          return (
            <span key={d} style={{ margin: '0 2px' }}>
              <button
                onClick={() => setLocale(d)}
                style={{ fontSize: 10, padding: '0 2px', border: '1px solid #cccccc' }}
              >
                {d}
              </button>
            </span>
          )
        })}
      </div>
      <div ref={ref} style={{ height: 300, width: '100%' }}></div>
    </div>
  )
}

export default Demo

基础示例

通过配置 page 属性，可以指定图表展示特定维度值的数据。

field: 分页字段。

currentValue: 当前展示的值。

registerAll()

const SimplePageDemo = () => {
  const containerRef = useRef(null)

  useEffect(() => {
    if (!containerRef.current) return

    const vseed: VSeed = {
      chartType: 'bar',
      dataset: [
        { month: 'Jan', sales: 100, year: '2022' },
        { month: 'Feb', sales: 120, year: '2022' },
        { month: 'Mar', sales: 130, year: '2022' },
        { month: 'Jan', sales: 150, year: '2023' },
        { month: 'Feb', sales: 180, year: '2023' },
        { month: 'Mar', sales: 190, year: '2023' },
      ],
      dimensions: [{ id: 'month' }],
      measures: [{ id: 'sales' }],
      page: {
        field: 'year',
        currentValue: '2022',
      },
    }

    const builder = Builder.from(vseed)
    const spec = builder.build()

    const vchart = new VChart(spec, { dom: containerRef.current })
    vchart.renderSync()

    return () => {
      vchart.release()
    }
  }, [])

  return (
    <div>
      <div style={{ marginBottom: 10 }}>当前展示 2022 年数据</div>
      <div ref={containerRef} style={{ width: '100%', height: 300 }} />
    </div>
  )
}

